      agentId: String(row.agent_id),
      duty: String(row.duty),
      status: String(row.status),
      briefing: String(row.briefing ?? ""),
      durationMs: Number(row.duration_ms ?? 0),
      startedAt: new Date(String(row.started_at)).toISOString(),
    })),
  };
}

