/**
 * Liveness and readiness for the whole office, in one JSON document.
 *
 * Answers "is the business actually running?", not just "is the process up?".
 * Reports the database, the audit chain, the autonomy scheduler, mail delivery,
 * the work queue and the money position — and never returns a secret, a
 * credential, a token or any customer content.
 *
 * Anonymous callers get the public projection: no money, no halt reason, no
 * mail account, no customer counts. A founder session (or the cron secret) gets
 * the full picture. The projection lives in `public-status.ts`, so there is no
 * field to forget to remove here.
 */
export const Route = createFileRoute("/api/health")({
  server: {
    handlers: {
      GET: async ({ request }: { request: Request }) => {
        try {
          const header = request.headers.get("authorization") ?? "";
          const token = header.toLowerCase().startsWith("bearer ") ? header.slice(7).trim() : "";
          const { full, health } = await getOfficeHealthForRequest({ data: { token } });
          const body = full
            ? health
            : publicStatus({
                checkedAt: health.checkedAt,
                company: health.company,
                version: health.version,
                halted: health.halted,
                database: { ok: health.database.ok },
                chain: { ok: health.chain.ok },
                scheduler: {
                  autonomyEnabled: health.scheduler.autonomyEnabled,
                  overdue: health.scheduler.overdue,
                  consecutiveFailures: health.scheduler.consecutiveFailures,
                },
                rateCard: { ok: health.rateCard.ok },
              });
          // A monitor polling health is also a liveness signal for the
          // scheduler. Keep the public wait tiny so an anonymous flood cannot
          // pin request threads; an authenticated operator may wait for the
          // catch-up tick.
          await nudgeScheduler({ data: { waitMs: full ? 2_000 : 250 } }).catch(() => undefined);
          return Response.json(body, {
            status: body.ok ? 200 : 503,
            headers: {
              "cache-control": "no-store",
              // Never let a search engine index a status document about the office.
              "x-robots-tag": "noindex, nofollow",
              ...(full ? { "x-health-scope": "full" } : { "x-health-scope": "public" }),
            },
          });
        } catch (error) {
          // A monitor must always get a document, never a stack trace or an
          // internal error string.
          console.error("[health] check failed", error);
          return Response.json(
            {
              ok: false,
              checkedAt: new Date().toISOString(),
              company: "Vantage-ARS",
              problems: ["Health check failed."],
            },
            { status: 503, headers: { "cache-control": "no-store" } },
          );
        }
      },
    },
  },
} as any);

# The office's heartbeat.
#
# Vercel Cron runs at most once per day on the Hobby plan, so the ten-minute
# tick that "docs/autonomy.md" describes runs from here instead: a scheduled
# workflow calling `GET /api/cron/floor` with `CRON_SECRET` as a repository
# secret. The route itself stays the only place the office can act; this file
# only rings the doorbell. Nothing is stored, committed or printed from the
# secret beyond the origin it came from.
#
# Requires one manual step by the founder:
#   GitHub → Settings → Secrets and variables → Actions → New repository secret
#   Name: CRON_SECRET — the same value set on Vercel for production.
name: office-scheduler

on:
  schedule:
    - cron: "*/10 * * * *"
  workflow_dispatch:

permissions: {}

concurrency:
  group: office-scheduler
  cancel-in-progress: false

jobs:
  tick:
    name: Run the office floor
    runs-on: ubuntu-latest
    timeout-minutes: 6

    steps:
      - name: Call /api/cron/floor
        env:
          CRON_SECRET: ${{ secrets.CRON_SECRET }}
          ENDPOINT: https://www.vantage-ars.co.za/api/cron/floor
        run: |
          set -eu

          if [ -z "$CRON_SECRET" ]; then
            echo "::error::CRON_SECRET is not set. Add it in Settings → Secrets and variables → Actions, with the same value the application has for production."
            exit 1
          fi

          code="$(curl -sS -L --max-time 300 -o response.txt -w "%{http_code}" \
            -H "Authorization: Bearer $CRON_SECRET" \
            "$ENDPOINT?ts=$(date +%s)")"

          cat response.txt

          case "$code" in
            200)
              echo "::notice::The office ran and healthy."
              echo "Office tick OK ($(date -u +%FT%TZ))" >> "$GITHUB_STEP_SUMMARY"
              cat response.txt >> "$GITHUB_STEP_SUMMARY"
              ;;
            401)
              echo "::error::The endpoint rejected the secret (401). The CRON_SECRET repository secret does not match the one configured on the host. Update one of them."
              exit 1
              ;;
            404)
              echo "::error::Not found (404). If the body above says \"Autonomy is not on.\", set AUTONOMY=on in the production environment on the host. Otherwise the deployment is stale — redeploy main."
              exit 1
              ;;
            500)
              echo "::error::The run failed server-side (500). The body above is the reason — commonly the circuit breaker engaged after repeated failures. Inspect /office."
              exit 1
              ;;
            *)
              echo "::error::Unexpected HTTP $code from the office endpoint."
              exit 1
              ;;
          esac
