const targets = await (await fetch("http://127.0.0.1:9222/json")).json();
const target = targets.find((entry) => entry.type === "page");
if (!target?.webSocketDebuggerUrl) throw new Error("No Chrome page target");
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener("open", resolve, { once: true });
  ws.addEventListener("error", reject, { once: true });
});
let id = 0;
const pending = new Map();
ws.addEventListener("message", (event) => {
  const message = JSON.parse(event.data);
  if (message.id && pending.has(message.id)) {
    const { resolve, reject } = pending.get(message.id);
    pending.delete(message.id);
    message.error ? reject(new Error(message.error.message)) : resolve(message.result);
  }
});
const send = (method, params = {}) => new Promise((resolve, reject) => {
  const commandId = ++id;
  pending.set(commandId, { resolve, reject });
  ws.send(JSON.stringify({ id: commandId, method, params }));
});
await send("Page.enable");
await send("Page.setDeviceMetricsOverride", { width: 1280, height: 1000, deviceScaleFactor: 1, mobile: false });
await send("Page.navigate", { url: "http://127.0.0.1:8080/game" });
await new Promise((resolve) => setTimeout(resolve, 1800));
const before = await send("Runtime.evaluate", { expression: "({heading:document.querySelector('h1')?.innerText, board:[...document.querySelectorAll('[role=img]')].find(x=>x.getAttribute('aria-label')?.startsWith('Game board'))?.getBoundingClientRect().toJSON(), start:!![...document.querySelectorAll('button')].find(b=>b.innerText.includes('Start run'))})", returnByValue: true });
if (!before.result.value.start) throw new Error(`Start control missing: ${JSON.stringify(before.result.value)}`);
await send("Runtime.evaluate", { expression: "[...document.querySelectorAll('button')].find(b => b.innerText.includes('Start run')).click()" });
await new Promise((resolve) => setTimeout(resolve, 190));
const running = await send("Runtime.evaluate", { expression: "({live:document.body.innerText.includes('Live run'), score:document.querySelector('[aria-live=polite]')?.innerText, head:[...document.querySelector('[aria-label^=\"Game board\"]')?.children||[]].findIndex(x=>x.className.includes('bg-accent'))})", returnByValue: true });
await send("Runtime.evaluate", { expression: "window.dispatchEvent(new KeyboardEvent('keydown',{key:'ArrowUp',bubbles:true}))" });
await new Promise((resolve) => setTimeout(resolve, 190));
const steered = await send("Runtime.evaluate", { expression: "({head:[...document.querySelector('[aria-label^=\"Game board\"]')?.children||[]].findIndex(x=>x.className.includes('bg-accent')), live:document.body.innerText.includes('Live run')})", returnByValue: true });
console.log(JSON.stringify({initial:before.result.value, running:running.result.value, afterArrowUp:steered.result.value}, null, 2));
if (!running.result.value.live || !steered.result.value.live || running.result.value.head === steered.result.value.head) throw new Error("Gameplay or keyboard steering did not advance");
const screenshot = await send("Page.captureScreenshot", { format: "jpeg", quality: 88, captureBeyondViewport: false });
await import("node:fs/promises").then(({ writeFile }) => writeFile("/tmp/opencode/signal-sweep.jpg", Buffer.from(screenshot.data, "base64")));
console.log("Saved latest 1280x1000 gameplay screenshot: /tmp/opencode/signal-sweep.jpg");
await send("Runtime.evaluate", { expression: "window.dispatchEvent(new KeyboardEvent('keydown',{key:' ',bubbles:true}))" });
await new Promise((resolve) => setTimeout(resolve, 80));
const paused = await send("Runtime.evaluate", { expression: "document.body.innerText.includes('SIGNAL HELD')", returnByValue: true });
console.log("Space pause:", paused.result.value);
ws.close();

